import{Et as e,Ot as t,n,qt as r}from"./chunks/framework.B_qehzBO.js";var i=JSON.parse(`{"title":"Hermes Stack: Un Clic, Todo un Servidor de IA","description":"La historia de Hermes Stack — convertir un Space gratuito de Hugging Face en un servidor de IA personal con agente, routers, dashboard y control por Telegram.","frontmatter":{"title":"Hermes Stack: Un Clic, Todo un Servidor de IA","description":"La historia de Hermes Stack — convertir un Space gratuito de Hugging Face en un servidor de IA personal con agente, routers, dashboard y control por Telegram."},"headers":[],"relativePath":"es/vibe-stories/story-2/index.md","filePath":"es/vibe-stories/story-2/index.md"}`),a={name:`es/vibe-stories/story-2/index.md`};function o(n,i,a,o,s,c){return r(),e(`div`,null,[...i[0]||=[t(`<h1 id="hermes-stack-un-clic-todo-un-servidor-de-ia" tabindex="-1">Hermes Stack: Un Clic, Todo un Servidor de IA <a class="header-anchor" href="#hermes-stack-un-clic-todo-un-servidor-de-ia" aria-label="Permalink to “Hermes Stack: Un Clic, Todo un Servidor de IA”">​</a></h1><p>Un servidor de IA personal normalmente significa factura de VPS, dominio, reverse proxy y un fin de semana perdido. Yo quería la misma potencia por <strong>$0</strong> — así que construí <strong><a href="https://github.com/Godde3s/hermes-stack" target="_blank" rel="noreferrer">Hermes Stack</a></strong>: un kit de despliegue que convierte un Space gratuito de Hugging Face en un nodo de IA completo y siempre encendido.</p><h2 id="que-aterriza-en-el-space" tabindex="-1">Qué aterriza en el Space <a class="header-anchor" href="#que-aterriza-en-el-space" aria-label="Permalink to “Qué aterriza en el Space”">​</a></h2><p>Un asistente — CLI, prompts guiados o un botón de GitHub Actions — provisiona un Space con tres piezas cooperando: el <a href="https://github.com/NousResearch/hermes-agent" target="_blank" rel="noreferrer">agente Hermes</a> para ejecución multi-paso, <a href="https://github.com/decolua/9router" target="_blank" rel="noreferrer">9Router</a> para agregación de proveedores y mi propio <a href="https://github.com/Godde3s/omnirouter" target="_blank" rel="noreferrer">OmniRouter</a> para enrutamiento de modelos — todo detrás de un dashboard web y una API compatible con OpenAI.</p><h2 id="las-partes-de-las-que-nadie-te-habla" tabindex="-1">Las partes de las que nadie te habla <a class="header-anchor" href="#las-partes-de-las-que-nadie-te-habla" aria-label="Permalink to “Las partes de las que nadie te habla”">​</a></h2><ul><li><strong>Keep-alive que respeta la plataforma</strong> — un bucle de ping amable evita que el Space gratuito se duerma, sin martillearlo.</li><li><strong>Backups horarios con restore real</strong> — el estado se guarda donde tú mandas; una reconstrucción se rehidrata en vez de empezar de cero.</li><li><strong>Telegram como plano de control</strong> — reiniciar, redesplegar, ver estado y seguir logs desde el móvil.</li><li><strong>Honestidad de dry-run</strong> — el asistente previsualiza cada paso antes de tocar tu cuenta y funciona con placeholders hasta que conectas secretos reales.</li></ul><h2 id="que-demuestra" tabindex="-1">Qué demuestra <a class="header-anchor" href="#que-demuestra" aria-label="Permalink to “Qué demuestra”">​</a></h2><p>Hermes Stack es empatía de DevOps codificada en Python: aprovisionamiento idempotente, runtime observable, fallos aburridos y recuperables. Es el proyecto que mis amigos me piden explicar — y la forma más rápida de entender cómo pienso el despliegue: <strong>si no es reproducible desde cero, no está desplegado.</strong></p>`,8)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};